    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof applyLabels>>, TError,ApplyLabelsMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof applyLabels>>, TError,ApplyLabelsMutationVariables, TContext> => {

const mutationKey = getApplyLabelsMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof applyLabels>>, ApplyLabelsMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  applyLabels(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ApplyLabelsMutationResult = NonNullable<Awaited<ReturnType<typeof applyLabels>>>
    export type ApplyLabelsMutationBody = BodyType<LabelApplyInput>
    export type ApplyLabelsMutationError = ErrorType<unknown>
    export type ApplyLabelsMutationVariables = {data: BodyType<LabelApplyInput>}

    /**
 * @summary Apply reviewed classifications to Gmail labels
 */
export const useApplyLabels = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof applyLabels>>, TError,ApplyLabelsMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof applyLabels>>,
        TError,
        ApplyLabelsMutationVariables,
        TContext
      > => {
      return useMutation(getApplyLabelsMutationOptions(options));
    }

